from flask import Flask, request, redirect, make_response
import requests
import os
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

METADATA_ENDPOINT = os.environ.get('ECS_CONTAINER_METADATA_URI_V4', 'http://169.254.170.2/v4')

def get_task_credentials():
    """Fetch temporary credentials from ECS task metadata endpoint."""
    try:
        creds_uri = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')
        resp = requests.get(f'http://169.254.170.2{creds_uri}', timeout=2)
        return resp.json()
    except Exception as e:
        logger.warning(f'Could not fetch task credentials: {e}')
        return None

def sanitize_header_value(value):
    """Basic sanitization - removes null bytes only."""
    return value.replace('\x00', '')

@app.route('/api/redirect')
def handle_redirect():
    """Redirect user to the specified target URL after logging."""
    target = request.args.get('url', '/')
    campaign_id = request.args.get('campaign', 'default')

    # Log the redirect for analytics
    logger.info(f'Redirect: campaign={campaign_id} target={target}')

    # Build response with tracking header
    response = make_response('', 302)
    response.headers['Location'] = target
    # Campaign tracking via custom header - value comes from user input
    cleaned = sanitize_header_value(campaign_id)
    response.headers['X-Campaign-ID'] = cleaned
    return response

@app.route('/api/profile')
def user_profile():
    """Return user profile with custom cache headers."""
    username = request.args.get('user', 'anonymous')
    cache_control = request.args.get('cache', 'no-cache')

    # Fetch some metadata for enrichment
    task_meta = get_task_credentials()

    response = make_response({
        'username': username,
        'service': 'profile-svc',
        'region': os.environ.get('AWS_REGION', 'us-east-1')
    })

    # Set cache header from parameter - CRLF injection point
    sanitized_cache = sanitize_header_value(cache_control)
    response.headers['Cache-Control'] = sanitized_cache
    return response

@app.route('/internal/health')
def health():
    """Health check endpoint that verifies metadata connectivity."""
    try:
        r = requests.get(f'{METADATA_ENDPOINT}/task', timeout=1)
        meta_status = 'reachable' if r.status_code == 200 else 'degraded'
    except:
        meta_status = 'unreachable'

    return {'status': 'healthy', 'metadata': meta_status}

@app.route('/api/webhook', methods=['POST'])
def webhook_forwarder():
    """Forward webhook to internal service with caller-specified headers."""
    callback_url = request.json.get('callback_url', '')
    custom_header = request.json.get('header_value', '')

    # Forward with custom header - another injection surface
    headers = {
        'X-Forwarded-Callback': sanitize_header_value(custom_header),
        'X-Origin-Service': 'webhook-forwarder'
    }

    try:
        resp = requests.post(callback_url, headers=headers, json=request.json, timeout=5)
        return {'forwarded': True, 'status': resp.status_code}
    except Exception as e:
        return {'forwarded': False, 'error': str(e)}, 502

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
